    JSONArray recent=new MemoryLedger(store).recent(message.optString("id"));JSONObject previous=null;for(int i=recent.length()-1;i>=0;i--)if(recent.getJSONObject(i).optString("role").equals("user")){previous=recent.getJSONObject(i);break;}if(previous==null||previous.optBoolean("careDeferred"))return ordinary;JSONArray ids=previous.optJSONArray("memoryIds");JSONObject target=null;int choices=0;if(ids!=null)for(int i=0;i<ids.length();i++){JSONObject r=store.one("memories",ids.getString(i));if(r==null)continue;JSONObject care=MemoryCare.inspect(r);if(care.optString("level").equals("actionable")&&care.optString("kind").equals("reminder_time")&&!care.optBoolean("deferred")&&care.optString("sourceId").equals(previous.optString("id"))){choices++;if(r.optString("id").equals(reference))target=r;}}if(choices!=1||target==null)return ordinary;
