    JSONObject day=prior;if(!resolved(day))day=target.optJSONObject("time");long dayStart=resolved(day)&&Arrays.asList("day","part_of_day").contains(day.optString("precision"))?day.optLong("start"):prior!=null&&prior.optBoolean("needsMeridiem")?prior.optLong("dateStart"):0;if(dayStart<=0)return ordinary;JSONObject original=prior!=null&&prior.optJSONObject("anchor")!=null?prior.optJSONObject("anchor"):day.optJSONObject("anchor");if(original==null)return ordinary;ZoneId tz=ZoneId.of(original.optString("zone",zone(message)));LocalDate date=Instant.ofEpochMilli(dayStart).atZone(tz).toLocalDate();String clockRaw=raw;if(prior!=null&&prior.optBoolean("needsMeridiem")&&raw.matches("上午|早上|早晨|下午|晚上|凌晨"))clockRaw=raw+prior.optInt("candidateHour")+"点"+prior.optInt("candidateMinute")+"分";JSONObject clockMessage=new JSONObject(message.toString()).put("capturedZone",tz.getId());JSONObject combined=resolve(date.toString()+" "+clockRaw,clockMessage,false,null);if(!resolved(combined)&&!combined.optBoolean("needsMeridiem"))return ordinary;
